# Python 3
from typing import List

def f(L: int, Q: int, S: str, strs: List[str]):
    dp = [[[0 for _ in range(36)] for _ in range(1 << L)] for _ in range(L + 1)]
    dp[0][0][0] = 1
    for i in range(L):
        for mask in range(1 << (L - i - 1)):
            for carry in range(36):
                cur = carry * 10 + int(S[i])
                if cur < 10:
                    dp[i + 1][mask | (1 << i)][carry % 10] += dp[i][mask][carry]
                cur = carry / 10 + int(S[i])
                if cur < 10:
                    dp[i + 1][mask | (1 << i)][carry % 10] += dp[i][mask][carry]
                cur = carry * 10 + int(S[i])
                if cur >= 10:
                    dp[i + 1][mask | (1 << i)][carry % 10] += dp[i][mask][carry]
                cur = carry / 10 + int(S[i])
                if cur >= 10:
                    dp[i + 1][mask | (1 << i)][carry % 10] += dp[i][mask][carry]
    res = 0
    for mask in range(1 << L):
        for carry in range(36):
            for j in range(Q):
                if [mask >> i & 1 == (ord(str[i]) - ord('0')) for i in range(L)]:
                    res += dp[L][mask][carry] * ((strs[j].count('?') == L) and (strs[j].count('0') + strs[j].count('1') == (L - strs[j].count('?'))))
    return res
